var s={en:`Organizers must upload PDF schedules and event posters. Content is untrusted and may exceed 50 MB. Files are not public until processing succeeds.`,ua:`Організатори завантажують PDF-програми та афіші. Вміст недовірений і може перевищувати 50 МБ. Файли не публікують до успішної обробки.`};var n={en:[`Add temporary storage, metadata and background inspection.`,`Define upload ownership, size/type limits and safe published links.`,`Handle malicious files, upload expiry and worker failures.`],ua:[`Додай тимчасове сховище, метадані й фонову перевірку.`,`Визнач власника завантаження, ліміти типу/розміру та безпечні посилання.`,`Оброби шкідливі файли, прострочення та збої воркера.`]};var i=[{en:`Unverified files cannot reach the public serving path.`,ua:`Неперевірені файли не потрапляють до публічного доступу.`},{en:`Only authorized organizers can publish their files.`,ua:`Лише уповноважені організатори публікують файли.`}];var r={scenario:s,tasks:n,checks:i};export{i as checks,r as default,s as scenario,n as tasks};